#!/usr/bin/env python3
from pathlib import Path
import re
p=Path('public/index.html'); h=p.read_text(encoding='utf-8')

# Carousel controls
controls='<div class="sm-format-carousel-controls"><button type="button" class="sm-format-carousel-prev" aria-label="Imagem anterior">‹</button><button type="button" class="sm-format-carousel-next" aria-label="Próxima imagem">›</button></div>'
if 'sm-format-carousel-controls' not in h:
    h,n=re.subn(r'(<div class="sm-format-carousel-track">.*?</div>)(</div>)',lambda m:m.group(1)+controls+m.group(2),h,count=3,flags=re.S)
    if n!=3: raise SystemExit(f'carousel controls: {n}/3')
h=re.sub(r'<script id="sm-format-carousels-v2-js">.*?</script>','',h,flags=re.S)
h=re.sub(r'<script id="sm-carousel-refinements-v3-js">.*?</script>','',h,flags=re.S)
h=re.sub(r'<script id="sm-carousel-refinements-v4-js">.*?</script>','',h,flags=re.S)
h=re.sub(r'<style id="sm-carousel-refinements-v3">.*?</style>','',h,flags=re.S)
h=re.sub(r'<style id="sm-carousel-refinements-v4">.*?</style>','',h,flags=re.S)
css='''<style id="sm-carousel-refinements-v4">.sm-format-carousel{overflow:visible!important}.sm-format-carousel-track{overflow:hidden!important;border-radius:inherit}.sm-format-carousel-controls{position:absolute;z-index:8;left:50%;bottom:14px;transform:translateX(-50%);display:flex;gap:10px}.sm-format-carousel-controls button{display:grid;place-items:center;width:42px;height:42px;padding:0;border:1px solid rgba(110,86,205,.18);border-radius:50%;background:#fff;box-shadow:0 9px 26px rgba(55,40,107,.14);color:#6f57cc;font:700 30px/1 Arial,sans-serif;cursor:pointer}.sm-format-v2-unit-card .sm-format-carousel-slide{left:8%!important;width:84%!important;right:auto!important}@media(max-width:720px){.sm-format-carousel-controls{bottom:9px}.sm-format-carousel-controls button{width:36px;height:36px;font-size:25px}.sm-format-v2-unit-card .sm-format-carousel-slide{left:5%!important;width:90%!important}}</style>'''
h=h.replace('</head>',css+'</head>',1)
js='''<script id="sm-carousel-refinements-v4-js">(function(){[].slice.call(document.querySelectorAll('[data-sm-carousel]')).forEach(function(r){var s=[].slice.call(r.querySelectorAll('[data-sm-carousel-slide]'));if(s.length<2)return;var i=Math.max(0,s.findIndex(function(x){return x.classList.contains('is-active')})),t=null,d=2200;function show(n){s[i].classList.remove('is-active');i=(n+s.length)%s.length;s[i].classList.add('is-active')}function stop(){if(t){clearInterval(t);t=null}}function start(){stop();if(!document.hidden)t=setInterval(function(){show(i+1)},d)}var p=r.querySelector('.sm-format-carousel-prev'),n=r.querySelector('.sm-format-carousel-next');if(p)p.onclick=function(e){e.preventDefault();show(i-1);start()};if(n)n.onclick=function(e){e.preventDefault();show(i+1);start()};r.addEventListener('mouseenter',stop);r.addEventListener('mouseleave',start);document.addEventListener('visibilitychange',function(){document.hidden?stop():start()});start()})})();</script>'''
h=h.replace('</body>',js+'</body>',1)

# Remove duplicate BÔNUS wording inside the format units
h=h.replace('<h3 class="sm-format-v2-title"><strong>50</strong><span>BÔNUS • Super-resumos</span></h3>','<h3 class="sm-format-v2-title"><strong>50</strong><span>Super-resumos</span></h3>',1)
h=h.replace('<h3 class="sm-format-v2-title"><strong>190</strong><span>BÔNUS • Supercards</span></h3>','<h3 class="sm-format-v2-title"><strong>190</strong><span>Supercards</span></h3>',1)
h=h.replace('<p><strong>Você recebe como bônus:</strong> o essencial de cada tema condensado para retomar pontos importantes com rapidez e clareza.</p>','<p>O essencial de cada tema condensado para retomar pontos importantes com rapidez e clareza.</p>',1)
h=h.replace('<p><strong>Você recebe como bônus:</strong> conceitos-chave em cards objetivos para reforçar conteúdos e fazer revisões curtas ao longo da rotina.</p>','<p>Conceitos-chave em cards objetivos para reforçar conteúdos e fazer revisões curtas ao longo da rotina.</p>',1)
h=re.sub(r'<style id="sm-bonus-refinement-v4">.*?</style>','',h,flags=re.S)
h=h.replace('</head>','<style id="sm-bonus-refinement-v4">.sm-format-v2-bonus-badge{display:flex!important;width:max-content!important;margin:0 0 16px!important;padding:10px 19px!important;border-radius:999px!important;background:linear-gradient(135deg,#f36a25,#ff496b)!important;color:#fff!important;font-size:13px!important;font-weight:950!important;letter-spacing:.12em!important;box-shadow:0 10px 24px rgba(243,106,37,.22)!important}</style></head>',1)

# Before/after: map is left at 50%, text right, all white/no paper card
url='https://static.wixstatic.com/media/1a67b8_b19132c7753849e08a076d81791245a4~mv2.png/v1/fit/w_1400,h_990/file.webp'
sec=f'''<section class="sm-visual-study sm-visual-compare-v2" id="estudo-visual" aria-labelledby="sm-visual-study-title"><div class="sm-vc-shell"><header class="sm-vc-intro"><span class="sm-vc-eyebrow">VEJA A DIFERENÇA NA PRÁTICA</span><h2 id="sm-visual-study-title">A mesma matéria. <span>Uma forma muito mais visual de entender.</span></h2><p>Arraste a barra para comparar o texto corrido com a organização visual dos Supermapas.</p></header><div class="sm-vc-compare" data-sm-before-after style="--sm-vc-position:50%"><div class="sm-vc-before"><div class="sm-vc-text-wrap"><span class="sm-vc-side-label sm-vc-side-label-text">TEXTO CORRIDO</span><h3>Crase</h3><p>A crase representa a fusão de duas vogais idênticas, normalmente a preposição <strong>a</strong> com o artigo feminino <strong>a</strong> ou <strong>as</strong>. Para verificar sua ocorrência, é necessário observar a regência do termo anterior e se o termo seguinte admite artigo feminino.</p><p>Seu emprego pode ser obrigatório diante de palavras femininas quando houver regência, em locuções femininas e na indicação de horas. Em alguns casos, pode ser facultativo, como diante de nomes próprios femininos e pronomes possessivos.</p><p>Não ocorre diante de palavras masculinas, verbos no infinitivo e pronomes pessoais. A análise depende sempre da relação entre os termos da frase.</p></div></div><div class="sm-vc-after"><div class="sm-vc-map-wrap"><span class="sm-vc-side-label sm-vc-side-label-map">COM SUPERMAPAS</span><img src="{url}" alt="Supermapa sobre crase" loading="lazy" decoding="async"/></div></div><div class="sm-vc-divider"><span><b>↔</b></span></div><input class="sm-vc-range" type="range" min="8" max="92" value="50" aria-label="Comparar texto corrido com Supermapas"/></div><div class="sm-vc-benefits"><div><b>01</b><span><strong>Encontre mais rápido</strong><small>Regras e exceções ficam visualmente separadas.</small></span></div><div><b>02</b><span><strong>Entenda as relações</strong><small>O conteúdo deixa de parecer um bloco único de texto.</small></span></div><div><b>03</b><span><strong>Revise sem reler tudo</strong><small>Volte aos pontos-chave com muito mais praticidade.</small></span></div></div></div></section>'''
h,n=re.subn(r'<section class="sm-visual-study sm-visual-compare-v2" id="estudo-visual".*?</section>',sec,h,count=1,flags=re.S)
if n!=1: raise SystemExit('comparison section missing')
h=re.sub(r'<style id="sm-visual-compare-v2-css">.*?</style>','',h,flags=re.S);h=re.sub(r'<style id="sm-visual-compare-v3-css">.*?</style>','',h,flags=re.S);h=re.sub(r'<style id="sm-visual-compare-v4-css">.*?</style>','',h,flags=re.S)
vc='''<style id="sm-visual-compare-v4-css">.sm-visual-compare-v2{padding:92px 24px;background:#fff!important}.sm-vc-shell{width:min(1180px,100%);margin:auto}.sm-vc-intro{text-align:center;max-width:860px;margin:0 auto 40px}.sm-vc-eyebrow{display:inline-block;margin-bottom:12px;font-size:12px;font-weight:900;letter-spacing:.16em;color:#7357d7}.sm-vc-intro h2{margin:0;color:#292534;font-size:clamp(34px,5vw,60px);line-height:1;letter-spacing:-.045em;font-weight:900}.sm-vc-intro h2 span{color:#7559df}.sm-vc-intro p{max-width:700px;margin:18px auto 0;color:#6f6978;font-size:17px;line-height:1.6}.sm-vc-compare{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden;background:#fff;border:0!important;border-radius:20px;box-shadow:0 24px 65px rgba(61,47,111,.10);isolation:isolate}.sm-vc-before,.sm-vc-after{position:absolute;inset:0;background:#fff}.sm-vc-before{z-index:1}.sm-vc-text-wrap{box-sizing:border-box;width:100%;height:100%;padding:7% 7.5%;display:flex;flex-direction:column;justify-content:center;background:#fff}.sm-vc-text-wrap h3{margin:0 0 22px;font:900 clamp(28px,3.5vw,48px)/1 Arial,sans-serif;color:#302a39}.sm-vc-text-wrap p{max-width:96%;margin:0 0 16px;font:500 clamp(12px,1.3vw,17px)/1.65 Arial,sans-serif;color:#625c69}.sm-vc-after{z-index:2;clip-path:inset(0 calc(100% - var(--sm-vc-position)) 0 0)}.sm-vc-map-wrap{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:2.5%;background:#fff}.sm-vc-map-wrap img{width:100%;height:100%;object-fit:contain}.sm-vc-side-label{position:absolute;z-index:3;top:18px;padding:9px 13px;border-radius:999px;font-size:10px;font-weight:900;letter-spacing:.1em}.sm-vc-side-label-map{left:18px;background:#7458dd;color:#fff}.sm-vc-side-label-text{right:18px;background:#f2effb;color:#6f59c7}.sm-vc-divider{position:absolute;z-index:4;top:0;bottom:0;left:var(--sm-vc-position);width:3px;background:#fff;box-shadow:0 0 0 1px rgba(83,60,169,.16);transform:translateX(-50%);pointer-events:none}.sm-vc-divider span{position:absolute;top:50%;left:50%;width:58px;height:58px;border-radius:50%;display:grid;place-items:center;background:#fff;color:#7559df;box-shadow:0 10px 28px rgba(54,38,112,.22);transform:translate(-50%,-50%)}.sm-vc-range{position:absolute;z-index:5;inset:0;width:100%;height:100%;opacity:0;cursor:ew-resize}.sm-vc-benefits{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:22px}.sm-vc-benefits>div{display:flex;gap:14px;padding:18px 20px;border:1px solid #ece8f5;background:#fff;border-radius:18px}.sm-vc-benefits b{display:grid;place-items:center;flex:0 0 38px;height:38px;border-radius:12px;background:#f0ebff;color:#7155d4}.sm-vc-benefits span{display:flex;flex-direction:column;gap:4px}.sm-vc-benefits strong{color:#302c3b;font-size:14px}.sm-vc-benefits small{color:#777180;font-size:12px}@media(max-width:720px){.sm-visual-compare-v2{padding:62px 16px}.sm-vc-intro h2{font-size:36px}.sm-vc-compare{aspect-ratio:4/5}.sm-vc-text-wrap{padding:13% 8%}.sm-vc-text-wrap h3{font-size:27px}.sm-vc-text-wrap p{font-size:11px;line-height:1.55}.sm-vc-benefits{grid-template-columns:1fr}}</style>'''
h=h.replace('</head>',vc+'</head>',1)

if h.count('sm-format-carousel-controls')<3 or 'value="50"' not in h: raise SystemExit('refinement validation failed')
p.write_text(h,encoding='utf-8');print('Applied preview refinements v4.')
